// Each check tests one misconception. Answers stay in memory; only explicit
// completion is saved. This is practice, not a certification or skills score.
export const exercises = {
  'desired-state': {task:'In a new empty practice directory, use the local start workflow to initialise the built-in terraform_data example. Before apply, predict the number of creates.',route:'workflow/start',question:'What does the configuration primarily describe?',options:['The desired result','An exact top-to-bottom execution order','A backup of current cloud data'],correct:0,explanation:'Configuration describes a desired result. Terraform computes actions and ordering from configuration, state and dependencies.'},
  'resources-providers': {task:'Read terraform_data.message in the local example. Identify its resource type, local name and complete address.',route:'workflow/start',question:'Which component determines where Terraform stores state?',options:['The provider alias','The backend','The resource local name'],correct:1,explanation:'The backend controls state storage. Providers implement resource and data-source interactions with services.'},
  'mental-model': {task:'Try the external-change scenario in the simulator. Explain why the recorded binding remains the same while the proposed update changes.',question:'Does restoring a state snapshot restore deleted database contents?',options:['Yes, state contains all application data','Only when the workspace has the same name','No, state records bindings and metadata'],correct:2,explanation:'State is not a backup of the managed service’s data. Infrastructure and data recovery need their own procedures.'},
  'command-lifecycle': {task:'In the local practice project, run fmt -check, validate and plan. Compare what each result establishes.',route:'workflow/start',question:'What does a successful validate establish?',options:['The target account and cost are correct','The configuration is internally consistent','Every apply will succeed'],correct:1,explanation:'validate checks configuration consistency. It does not prove the target identity, remote permissions, cost or success of apply.'},
  'variables-values': {task:'Follow the variable-file workflow in a new practice directory. Predict the string and list values in the plan, verify the applied output, then inspect an input change without applying it.',route:'workflow/variables',question:'Does sensitive = true guarantee a value is absent from state?',options:['Yes, all sensitive values are omitted','No, sensitive values can still be stored','Yes, unless the output is a string'],correct:1,explanation:'Sensitive marking affects many displays. It does not guarantee values are absent from state or saved plan artifacts.'},
  'read-plan': {task:'Use the local practice project to change Hello, Terraform to Hello again. Read the plan and explain the update before applying.',route:'workflow/change',question:'You see an unexplained replacement. What is the next step?',options:['Apply because the plan completed','Force a targeted apply','Investigate the reason and target before approval'],correct:2,explanation:'A completed plan is a proposal, not approval. Understand replacement reasons, dependencies and the target before proceeding.'},
  'modules-addresses': {task:'Follow the local child-module workflow. Verify the moved address, preserved id and unchanged output before calling the exercise complete.',route:'workflow/module-move',question:'What is the purpose of a suitable moved block?',options:['Record an intended address transition','Copy the real object into another cloud','Turn off provider replacement rules'],correct:0,explanation:'A moved block tells Terraform how an existing binding transitions to a new address. Inspect the plan for any additional changes.'},
  'backends-teams': {task:'Open the lock troubleshooting guide. Choose active, unknown and abandoned ownership and compare the next checks.',route:'recipe/state-locked',question:'An active CI run owns a lock. What should you do?',options:['Disable locking','Force-unlock immediately','Wait or coordinate with that run’s owner'],correct:2,explanation:'An active run may be writing the same state. Coordinate rather than allowing competing operations.'}
};
export function checkAnswer(id,value) {
  const exercise=exercises[id];
  if(!exercise||!Number.isInteger(value)||value<0||value>=exercise.options.length)return null;
  return {correct:value===exercise.correct,explanation:exercise.explanation};
}
